func firstName(email string) string {
	name := email
	if i := strings.Index(email, "@"); i > 0 {
		name = email[:i]
	}
	if i := strings.IndexAny(name, "._-"); i > 0 {
		name = name[:i]
	}
	if len(name) > 0 {
		return strings.ToUpper(name[:1]) + name[1:]
	}
	return name
}

